# =============================================================================
#  Extended_Model_Population.r
#  Population (virtual-individual) version of Extended_Model.r.
#
#  Extended_Model.r's .create.params() builds organ volumes (V*) and plasma
#  flows (Q*) from fixed literature fractions of a single point-estimate BW.
#  This script replaces that physiology block with per-individual organ mass
#  and blood flow generated by the PopGen algorithm (popgen_consts.R /
#  popgen_port.R), so the model is solved once per virtual individual instead
#  of once for a population-average body.
#
#  Mapping notes (see .map_popgen_individual() below for the exact code):
#   - Organ mass (kg) -> organ volume (L): popgen only generates organ MASS,
#     so volume is computed as V = M / density using standard per-organ
#     tissue densities (Brown et al. 1997; ICRP Publication 89), not by
#     treating mass as volume directly (an earlier version of this script
#     assumed unit density for every organ, which is the "V(organ) used to
#     be M(organ)" inconsistency this fixes). MK/ML/VPTC downstream use the
#     popgen organ mass directly rather than re-deriving mass from volume.
#   - Organ blood flow (popgen, L/h) -> plasma flow (model's Q*, L/time_scale):
#     multiplied by inv_time_scale (hours per time_scale unit) and by
#     (1 - Htc), exactly mirroring how Extended_Model.r derives its own QC
#     (QC <- QCC * BW^0.75 * (1 - Htc)) from a blood-flow-basis literature
#     constant.
#   - PopGen has no "rest of body" organ; its Bone compartment is the largest
#     tissue with no dedicated compartment in Extended_Model.r, so Bone
#     mass/flow is mapped onto the model's rest-of-body compartment (VR/QR),
#     per explicit request.
#   - Lung: popgen's own "Lung_flow" column is a cardiac-output placeholder,
#     not real lung-tissue perfusion (see popgen_port.R's header on
#     Lung_Bronchial_flow). The model's QLun is mapped from
#     Lung_Bronchial_flow (the actual pulmonary-tissue/bronchial perfusion),
#     matching the convention popgen_r_as_population() already uses elsewhere
#     in this project.
#   - GI tract: Extended_Model.r has a single lumped GI compartment, so
#     popgen's Stomach + Small intestine + Large intestine are used via
#     popgen_r()'s own GI_tract_mass_kg / GI_tract_flow (lump_GI = TRUE).
#   - Liver flow (QL) is mapped from popgen's "Liver_flow" only (the hepatic
#     ARTERY contribution) -- exactly as in Extended_Model.r, where portal
#     inflow from GI/Spleen/Pancreas is already handled separately inside
#     .ode.func()'s liver mass-balance equation. Do not use Liver_Total_flow
#     here, it would double-count the portal contribution.
#   - QC is defined as the sum of the mapped organ Q's (not popgen's own
#     `cardiac_output` field, which excludes the small lung-bronchial term)
#     so the plasma-flow balance (QBAL) is exact by construction.
#   - Chemical-specific PK parameters (Vmax, Km, RAF, partition coefficients,
#     rate constants) and the administered dose are NOT generated by popgen
#     and are therefore identical across individuals, exactly as in
#     Extended_Model.r; only physiology (organ mass/flow, and hence BW) varies
#     across the population.
#   - Hematocrit (Htc, .sample_Htc()): popgen does not generate it, and
#     Extended_Model.r uses one fixed Htc = 0.42 for everyone. Here each
#     individual instead draws its own Htc from a sex-specific truncated
#     normal (mean/sd backed out of standard ~41-51% male / ~36-46% female
#     clinical reference intervals), so plasma-basis flows/partition
#     coefficients (both scaled by (1 - Htc)) vary accordingly. Water
#     consumption remains the same fixed literature constant Extended_Model.r
#     uses; popgen does not generate that either.
#   - GFR (.gfr_age_factor()): GFRC (24.19 L/h/kg kidney, Corley 2005) is a
#     single filtration-rate-per-kidney-mass constant with no age dependence;
#     GFR = GFRC * VK alone assumes filtration efficiency per gram of kidney
#     tissue is the same at every age, when in reality it declines with age
#     (nephron loss/glomerulosclerosis) independent of gross kidney mass. A
#     literature-based relative age-decline factor (Davies & Shock 1950;
#     Lindeman et al. 1985 BLSA: ~0.5-0.7%/year of peak GFR after the ~30s
#     plateau) is applied on top of GFRC*VK. The factor is per-sex but both
#     sexes currently share the same slope -- the ~140 vs 120 mL/min/1.73m^2
#     male/female BASELINE gap in that literature is mostly a body/kidney-size
#     effect already captured by popgen's sex-specific VK, so it is
#     deliberately NOT applied a second time as a baseline multiplier here
#     (that would double-count the size-driven share of the sex gap).
#
#  Dependencies: popgen_consts.R and popgen_port.R must be in the working
#  directory (same convention Run_extended.r uses for Extended_Model.r).
# =============================================================================

library(deSolve)
library(tidyverse)

#=========================
# 0. PopGen dependencies
#=========================
if (!exists("POPGEN_CONSTS")) {
  if (file.exists("popgen_consts.R")) source("popgen_consts.R") else
    stop("Extended_Model_Population.r requires popgen_consts.R -- source() it first, or run from the folder containing it")
}
if (!exists("popgen_r")) {
  if (file.exists("popgen_port.R")) source("popgen_port.R") else
    stop("Extended_Model_Population.r requires popgen_port.R -- source() it first, or run from the folder containing it")
}

