#=========================
# 2. Required-input validation
#=========================
#'
#' @keywords internal
#'
.required_population_fields <- c("n", "dataset", "age_range", "bmi_range", "height_range",
                                  "prob_male", "ethnicity_probs", "population_type")

#'
#' @keywords internal
#'
.check_required <- function(user_input, fields) {
  missing_fields <- fields[!vapply(fields, function(f) {
    f %in% names(user_input) && !is.null(user_input[[f]]) && !(length(user_input[[f]]) == 1 && is.na(user_input[[f]]))
  }, logical(1))]
  if (length(missing_fields) > 0) {
    stop("Missing required input parameter(s): ", paste(missing_fields, collapse = ", "))
  }
}

#=========================
# 3. Population generation (organ mass & flow source)
#=========================
#' Generate the virtual population underlying this simulation
#'
#' Thin, validated wrapper around popgen_r() (popgen_port.R). All population
#' parameters below are REQUIRED in `user_input` -- there is no silent
#' default, since these are exactly the parameters that determine every
#' individual's organ mass and blood flow.
#'
#' @param user_input List that must contain:
#'   \item{n}{population size (accepted individuals)}
#'   \item{dataset}{"ICRP" or "P3M"}
#'   \item{age_range}{c(lower, upper) years}
#'   \item{bmi_range}{c(lower, upper) kg/m2}
#'   \item{height_range}{c(lower, upper) cm}
#'   \item{prob_male}{probability an individual is male}
#'   \item{ethnicity_probs}{c(White, Black, NonBlackHispanic); must sum <= 1}
#'   \item{population_type}{"Realistic" or "HighVariation"}
#'   May optionally contain `seed` (RNG seed; NULL if omitted).
#' @return list(pop = data.frame, n_discarded = integer), as returned by popgen_r()
#' @export
#'
.generate_population <- function(user_input) {
  .check_required(user_input, .required_population_fields)

  popgen_r(
    n = user_input$n,
    dataset = user_input$dataset,
    age_range = user_input$age_range,
    bmi_range = user_input$bmi_range,
    height_range = user_input$height_range,
    prob_male = user_input$prob_male,
    ethnicity_probs = user_input$ethnicity_probs,
    population_type = user_input$population_type,
    flow_units = "LitresPerHour",
    seed = if (is.null(user_input$seed)) NULL else user_input$seed,
    lump_GI = TRUE
  )
}

#=========================
# 4. Map one individual's popgen organ mass/flow onto the PBK compartments
#=========================
#' Map a single popgen individual onto Extended_Model.r's compartments
#'
#' @param ind One row of the data.frame returned by .generate_population()$pop
#'   (as produced by popgen_r(), with lump_GI = TRUE, flow_units = "LitresPerHour").
#' @param Htc Hematocrit fraction (fixed literature constant; popgen does not
#'   generate it).
#' @param inv_time_scale Hours per model time-scale unit (as computed by
#'   Extended_Model.r's .create.params(), e.g. 24 for "days").
#' @return list of BW plus every V*/Q* Extended_Model.r's ODE system needs.
#' @keywords internal
#'
.map_popgen_individual <- function(ind, Htc, inv_time_scale) {

  BW <- ind[["body_mass_kg"]]

  # --- Tissue densities (kg/L, equivalently g/mL): standard PBPK literature
  # values (Brown et al. 1997; ICRP Publication 89). Popgen supplies organ
  # MASS (kg), not volume -- treating mass as volume directly (implicit
  # density = 1 for every organ) was the unit inconsistency being fixed here;
  # volume is now computed as V = M / density per organ. Gonads and Pancreas
  # are not separately tabulated in Brown 1997, so they use the generic
  # soft-tissue value (same as Kidney/Liver/Muscle); verify against your
  # preferred source if you need more precision than these round literature
  # values.
  dens <- c(Adipose = 0.92, Brain = 1.04, Gonads = 1.05, Heart = 1.03,
            Lung = 1.05, Muscle = 1.04, Skin = 1.10, Spleen = 1.06,
            Pancreas = 1.05, GI = 1.04, Liver = 1.05, Kidney = 1.05, Bone = 1.30)

  # --- Tissue masses (kg), straight from popgen ---
  MAdi <- ind[["Adipose_mass_kg"]]
  MBra <- ind[["Brain_mass_kg"]]
  MGon <- ind[["Gonads_mass_kg"]]
  MHea <- ind[["Heart_mass_kg"]]
  MLun <- ind[["Lung_mass_kg"]]
  MMus <- ind[["Muscle_mass_kg"]]
  MSki <- ind[["Skin_mass_kg"]]
  MSpl <- ind[["Spleen_mass_kg"]]
  MPan <- ind[["Pancreas_mass_kg"]]
  MGI  <- ind[["GI_tract_mass_kg"]]   # lumped Stomach + Small intestine + Large intestine
  MLiv <- ind[["Liver_mass_kg"]]
  MKid <- ind[["Kidneys_mass_kg"]]
  MR <- ind[["Bone_mass_kg"]]      # Bone -> rest of body (no dedicated bone compartment in the model)

  # --- Tissue volumes (L): V = M / density ---
  VAdi <- MAdi / dens[["Adipose"]]
  VBra <- MBra / dens[["Brain"]]
  VGon <- MGon / dens[["Gonads"]]
  VHea <- MHea / dens[["Heart"]]
  VLun <- MLun / dens[["Lung"]]
  VMus <- MMus / dens[["Muscle"]]
  VSki <- MSki / dens[["Skin"]]
  VSpl <- MSpl / dens[["Spleen"]]
  VPan <- MPan / dens[["Pancreas"]]
  VGI  <- MGI  / dens[["GI"]]
  VL   <- MLiv / dens[["Liver"]]
  VK   <- MKid / dens[["Kidney"]]
  VR   <- MR / dens[["Bone"]]

  # --- Tissue plasma flows (L/time_scale): popgen flow (L/h, blood basis) ->
  # model flow (L/time_scale, plasma basis), mirroring how Extended_Model.r's
  # own QC <- QCC * BW^0.75 * (1 - Htc) converts a blood-flow-basis literature
  # constant into a plasma flow ---
  to_model_Q <- function(Lph) Lph * inv_time_scale * (1 - Htc)

  QAdi <- to_model_Q(ind[["Adipose_flow"]])
  QBra <- to_model_Q(ind[["Brain_flow"]])
  QGon <- to_model_Q(ind[["Gonads_flow"]])
  QHea <- to_model_Q(ind[["Heart_flow"]])
  QLun <- to_model_Q(ind[["Lung_Bronchial_flow"]])  # actual lung-tissue perfusion; Lung_flow itself is a CO placeholder, not tissue flow
  QMus <- to_model_Q(ind[["Muscle_flow"]])
  QSki <- to_model_Q(ind[["Skin_flow"]])
  QSpl <- to_model_Q(ind[["Spleen_flow"]])
  QPan <- to_model_Q(ind[["Pancreas_flow"]])
  QGI  <- to_model_Q(ind[["GI_tract_flow"]])
  QL   <- to_model_Q(ind[["Liver_flow"]])   # hepatic ARTERY only; portal inflow from GI/Spleen/Pancreas is handled inside .ode.func()'s liver balance
  QK   <- to_model_Q(ind[["Kidneys_flow"]])
  QR   <- to_model_Q(ind[["Bone_flow"]])    # Bone -> rest of body


  QC <- QK + QL + QR + QAdi + QBra + QGon + QHea + QLun + QMus + QSki + QSpl + QPan + QGI

 MBal <- BW - (MR + MLiv + MKid + MAdi + MBra + MGon + MHea + MLun + MMus + MSki + MSpl + MPan + MGI) 
  list(
    BW = BW,
    QC = QC, QK = QK, QL = QL, QR = QR, QAdi = QAdi, QBra = QBra, QGon = QGon,
    QHea = QHea, QLun = QLun, QMus = QMus, QSki = QSki, QSpl = QSpl, QPan = QPan, QGI = QGI,
    VAdi = VAdi, VBra = VBra, VGon = VGon, VHea = VHea, VLun = VLun, VMus = VMus,
    VSki = VSki, VSpl = VSpl, VPan = VPan, VGI = VGI, VL = VL, VK = VK, VR = VR,
    MLiv = MLiv, MKid = MKid  # organ mass (kg), straight from popgen; used downstream for ML/MK/VPTC instead of re-deriving mass from volume with a second, possibly-inconsistent density
  )
}

#' Age-related correction factor for GFR, on top of GFRC * VK
#'
#' GFRC (Corley 2005) is a single filtration-rate-per-kidney-mass constant;
#' this factor layers in the well-documented decline of GFR per gram of
#' kidney tissue with age (nephron loss/glomerulosclerosis), which anatomical
#' kidney-mass scaling (VK) alone does not capture. Normalized to 1.0 at
#' `age_ref` (the literature plateau, ~30s), linearly declining by
#' `decline_per_year[sex]` fraction of peak per year thereafter, floored at
#' `f_min` to keep the correction physiologically plausible (not <=0) for
#' very old ages.
#'
#' `decline_per_year` is a per-sex named vector so the two sexes' decline
#' RATES can be tuned independently if future evidence supports it; both
#' currently share the same ~0.6%/year slope (midpoint of Davies & Shock
#' 1950's ~8 mL/min/1.73m^2 per decade off a 140 mL/min/1.73m^2 peak, and
#' Lindeman et al. 1985's ~0.75 mL/min/year off the same peak). The
#' male/female BASELINE GFR gap reported in that literature (~140 vs
#' ~120 mL/min/1.73m^2) is intentionally NOT reproduced here as a second,
#' separate multiplier -- it is predominantly a body/kidney-size effect
#' already carried by popgen's sex-specific VK (see .map_popgen_individual()
#' and the file header), and applying it again here would double-count it.
#'
#' @keywords internal
#'
.gfr_age_factor <- function(age, sex, age_ref = 30,
                             decline_per_year = c(Male = 0.006, Female = 0.006),
                             f_min = 0.3) {
  rate <- decline_per_year[[sex]]
  pmax(f_min, 1 - rate * pmax(0, age - age_ref))
}

#' Random per-individual hematocrit, sex-specific
#'
#' popgen does not generate hematocrit (see the file header), and
#' Extended_Model.r itself uses a single fixed Htc = 0.42 for every
#' individual. Real adult hematocrit is both sex-differentiated (testosterone
#' drives higher erythropoietin/red-cell mass in men; menstrual blood loss
#' lowers it in women) and has real inter-individual spread even within one
#' sex -- clinical reference intervals (~95% ranges) are approximately
#' 41-51% for men and 36-46% for women. `.HTC_REF` backs those out to a
#' mean/sd per sex (interval width / 1.96), and each individual draws its
#' own Htc from a normal distribution truncated to `lower`/`upper` (using
#' popgen_port.R's own .pg_truncated_norm_rnd(), the same truncation method
#' popgen uses for its own bounded draws) so sampling can never produce a
#' physiologically impossible hematocrit.
#'
#' @keywords internal
#'
.HTC_REF <- list(Male = c(mean = 0.46, sd = 0.025), Female = c(mean = 0.41, sd = 0.025))

.sample_Htc <- function(sex, lower = 0.20, upper = 0.60) {
  p <- .HTC_REF[[sex]]
  .pg_truncated_norm_rnd(p[["mean"]], p[["sd"]], lower, upper)
}

#=========================
# 5. Parameters of the model, for one popgen individual
#=========================
#' Build Extended_Model.r-compatible params for one popgen individual
#'
#' Same chemical-specific PK parameters, partition coefficients, rate
#' constants and dosing fields as Extended_Model.r's .create.params(); the
#' only difference is that BW and every V*/Q* come from `ind` (one row of a
#' popgen population) via .map_popgen_individual(), instead of from fixed
#' literature V*C/Q*C fractions of a user-supplied BW.
#'
#' @param user_input List with the same chemical/dosing fields .create.params()
#'   expects (chemical, admin_type, admin_dose, admin_time, ingestion,
#'   ingestion_time, exp_type, duration, and optionally time_scale). BW is
#'   NOT read from user_input here -- it comes from `ind`.
#' @param ind One row of the data.frame returned by .generate_population()$pop.
#' @param chem list(variables, PC) from .get_chemical_vars(user_input$chemical).
#' @export
#'
.create.params.population <- function(user_input, ind, chem) {
  with(as.list(user_input), {

    variables <- chem$variables
    PC <- chem$PC

    if (missing(time_scale) || is.na(time_scale)) {
      time_scale <- 1/24
    } else if (time_scale == "minutes") {
      time_scale <- 60
    } else if (time_scale == "hours") {
      time_scale <- 1
    } else if (time_scale == "days") {
      time_scale <- 1/24
    } else if (time_scale == "weeks") {
      time_scale <- (1/24)/7
    } else if (time_scale == "months") {
      time_scale <- ((1/24)/30)
    } else if (time_scale == "years") {
      time_scale <- ((1/24)/365)
    }
    inv_time_scale <- 1/time_scale

    # --- Chemical Specific Parameters (identical to Extended_Model.r) ---
    MW <- variables["MW",]
    Free <- variables["Free",]

    Vmax_baso_invitro <- variables["Vmax_baso_invitro", ]
    Km_baso <- variables["Km_baso", ] * variables["MW", ]
    Vmax_apical_invitro <- variables["Vmax_apical_invitro", ]
    Km_apical <- variables["Km_apical", ] * variables["MW", ]
    RAFbaso <- variables["RAFbaso", ]
    RAFapi <- variables["RAFapi", ]
    protein <- 2.0e-6
    GFRC <- 24.19 * inv_time_scale

    Htc <- .sample_Htc(ind[["sex"]])  # random per individual, sex-specific; popgen does not generate Htc (see .sample_Htc())

    # --- Partition Coefficients (Allendorf 2021); chemical-tissue property,
    # independent of popgen -- only organ VOLUME/FLOW is mapped from the
    # virtual population, not the chemical's partitioning behavior ---
    PR <- 0.1  # rest of body: (now applies to the popgen Bone compartment)
    PAdi <- (1 - Htc) * PC["Adipose", ]
    PBra <- (1 - Htc) * PC["Brain", ]
    PGon <- (1 - Htc) * PC["Gonads", ]
    PGI  <- (1 - Htc) * PC["Gut", ]
    PHea <- (1 - Htc) * PC["Heart", ]
    PL   <- (1 - Htc) * PC["Liver", ]
    PLun <- (1 - Htc) * PC["Lung", ]
    PMus <- (1 - Htc) * PC["Muscle", ]
    PSki <- (1 - Htc) * PC["Skin", ]
    PSpl <- (1 - Htc) * PC["Spleen", ]
    PPan <- (PGI + PSpl) / 2

    # --- Rate Constants (identical to Extended_Model.r) ---
    kdif <- 0.001 * inv_time_scale
    kabsc <- 2.12 * inv_time_scale
    kunabsc <- 7.06e-5 * inv_time_scale
    keffluxc <- variables["keffluxc", ] * inv_time_scale /24
    kbilec <- variables["kbilec", ] * inv_time_scale /24
    kurinec <- 0.063 * inv_time_scale
    water_consumption <- 1.36

    VplasC <- 0.0428  # fraction vol. of plasma (L/kg BW); not generated by popgen
    VfilC <- 4e-4      # fraction vol. of filtrate (L/kg BW); not generated by popgen
    VPTCC <- 1.35e-4   # vol. of proximal tubule cells (L/g kidney)

    # === Individual physiology from popgen ===
    phys <- .map_popgen_individual(ind, Htc, inv_time_scale)
    BW <- phys$BW
    QC <- phys$QC; QK <- phys$QK; QL <- phys$QL; QR <- phys$QR
    QAdi <- phys$QAdi; QBra <- phys$QBra; QGon <- phys$QGon; QHea <- phys$QHea
    QLun <- phys$QLun; QMus <- phys$QMus; QSki <- phys$QSki; QSpl <- phys$QSpl
    QPan <- phys$QPan; QGI <- phys$QGI
    VAdi <- phys$VAdi; VBra <- phys$VBra; VGon <- phys$VGon; VHea <- phys$VHea
    VLun <- phys$VLun; VMus <- phys$VMus; VSki <- phys$VSki; VSpl <- phys$VSpl
    VPan <- phys$VPan; VGI <- phys$VGI; VL <- phys$VL; VK <- phys$VK; VR <- phys$VR

    VPlas <- VplasC * BW
    Vfil <- VfilC * BW
    ML <- phys$MLiv * 1000   # mass of the liver (g); popgen mass directly, not re-derived from VL
    MK <- phys$MKid * 1000   # mass of the kidney (g); popgen mass directly, not re-derived from VK
    VKb <- VK * 0.16         # volume of blood in the kidney (L); Brown 1997
    VPTC <- MK * VPTCC       # VPTCC is L per GRAM of kidney MASS, so this must use MK (mass), not VK*1000 (which was only ~= kidney mass under the old density-1 assumption)
    MPTC <- VPTC * 1000

    PTC <- (VK / BW) * 1000 * 6e7  # number of PTC (cells/kg BW); Extended_Model.r derives this from the SAME
    # literature fraction (VKC) that also defines VK there, so the two stay self-consistent by construction.
    # Here VK is popgen's real per-individual kidney volume, not a fixed Brown 1997 population-average
    # fraction of BW -- using this individual's own VK/BW ratio (instead of a separate fixed VKC_lit
    # constant) keeps that same self-consistency instead of mixing a population-average kidney fraction
    # with this individual's own popgen-derived kidney volume everywhere else.

    Vmax_basoC <- (Vmax_baso_invitro * RAFbaso * PTC * protein * 60 * (MW / 1e12) * 1e6)  * inv_time_scale
    Vmax_apicalC <- (Vmax_apical_invitro * RAFapi * PTC * protein * 60 * (MW / 1e12) * 1e6)  * inv_time_scale
    Vmax_baso <- Vmax_basoC * BW^0.75
    Vmax_apical <- Vmax_apicalC * BW^0.75
    kbile <- kbilec * BW^(-0.25)
    kurine <- kurinec * BW^(-0.25)
    kefflux <- keffluxc * BW^(-0.25)
    GFR <- GFRC * VK * .gfr_age_factor(ind[["age"]], ind[["sex"]])
    kabs <- kabsc * BW^(-0.25)
    kunabs <- kunabsc * BW^(-0.25)


    return(list(
      "BW" = BW, 
      "Free" = Free, "QC" = QC, "QK" = QK, "QL" = QL, "QR" = QR,
      "QAdi" = QAdi, "QBra" = QBra, "QGon" = QGon, "QHea" = QHea,
      "QLun" = QLun, "QMus" = QMus, "QSki" = QSki, "QSpl" = QSpl,
      "QPan" = QPan, "QGI" = QGI,
      "VPlas" = VPlas, "VKb" = VKb, "Vfil" = Vfil, "VL" = VL,
      "VR" = VR, "ML" = ML,
      "VAdi" = VAdi, "VBra" = VBra, "VGon" = VGon, "VHea" = VHea,
      "VLun" = VLun, "VMus" = VMus, "VSki" = VSki, "VSpl" = VSpl, "VPan" = VPan,
      "VGI" = VGI, "MK" = MK,
      "VPTC" = VPTC, "Vmax_baso" = Vmax_baso, "Vmax_apical" = Vmax_apical,
      "kdif" = kdif, "Km_baso" = Km_baso, "Km_apical" = Km_apical,
      "kbile" = kbile, "kurine" = kurine, "kefflux" = kefflux,
      "GFR" = GFR, "kabs" = kabs, "kunabs" = kunabs,
      "PR" = PR, "PAdi" = PAdi, "PBra" = PBra, "PGon" = PGon, "PGI" = PGI,
      "PHea" = PHea, "PL" = PL, "PLun" = PLun, "PMus" = PMus, "PSki" = PSki,
      "PSpl" = PSpl, "PPan" = PPan, "water_consumption" = water_consumption,
      "admin_type" = admin_type, "admin_dose" = admin_dose,
      "admin_time" = admin_time, "ingestion" = ingestion,
      "ingestion_time" = ingestion_time, "duration" = duration,
      "time_scale" = time_scale, "exp_type" = exp_type
    ))

  })
}

