.custom.func <- function(){
  return()
}

#==============
# 9. ODEs System (identical to Extended_Model.r)
#==============
#'
#' @export
#'
.ode.func <- function(time, inits, params, custom.func) {
  with(as.list(c(inits, params)), {

    CR <- AR / VR
    CVR <- CR / PR
    

    CAdi <- AAdi / VAdi
    CVAdi <- CAdi / PAdi
   

    CBra <- ABra / VBra
    CVBra <- CBra / PBra
    

    CGon <- AGon / VGon
    CVGon <- CGon / PGon


    CHea <- AHea / VHea
    CVHea <- CHea / PHea


    CLun <- ALun / VLun
    CVLun <- CLun / PLun


    CMus <- AMus / VMus
    CVMus <- CMus / PMus


    CSki <- ASki / VSki
    CVSki <- CSki / PSki


    CSpl <- ASpl / VSpl
    CVSpl <- CSpl / PSpl

    Cpan <- APan / VPan
    CVPan <- Cpan / PPan

    CGI <- AGI / VGI
    CVGI <- CGI / PGI


    CKb <- AKb / VKb
    CVK <- CKb
    CPTC <- APTC / VPTC
    Cfil <- Afil / Vfil

    CL <- AL / VL
    CLiver <- AL / ML
    CVL <- CL / PL


    CA_free <- Aplas_free / VPlas
    CA <- CA_free / Free

    dAR <- QR * (CA - CVR) * Free

    dAAdi <- QAdi * (CA - CVAdi) * Free

    dABra <- QBra * (CA - CVBra) * Free

    dAGon <- QGon * (CA - CVGon) * Free

    dAHea <- QHea * (CA - CVHea) * Free

    dALun <- QLun * (CA - CVLun) * Free

    dAMus <- QMus * (CA - CVMus) * Free

    dASki <- QSki * (CA - CVSki) * Free

    dASpl <- QSpl * (CA - CVSpl) * Free

    dAPan <- QPan * (CA - CVPan) * Free

    dAdif <- kdif * (CKb - CPTC)
    dA_baso <- (Vmax_baso * CKb) / (Km_baso + CKb)
    dAKb <- QK * (CA - CVK) * Free - CA * GFR * Free - dAdif - dA_baso
    dACl <- CA * GFR * Free

    dAefflux <- kefflux * APTC
    dA_apical <- (Vmax_apical * Cfil) / (Km_apical + Cfil)
    dAPTC <- dAdif + dA_apical + dA_baso - dAefflux

    dAfil <- CA * GFR * Free - dA_apical - Afil * kurine

    dAurine <- kurine * Afil

    dALumen <- ingestion + - kabs * ALumen- kunabs * ALumen

    dAGI <- kabs * ALumen + QGI*(CA - CVGI) * Free
    dAabsLumen <- kabs * ALumen

    dAfeces <-  kunabs * ALumen + kbile * AL

    dAL <- QL * (CA - CVL) * Free - kbile * AL + QGI*(CVGI - CVL) * Free +
          QSpl*(CVSpl-CVL)*Free +QPan*(CVPan-CVL)*Free

    dAbile <- kbile * AL
    amount_per_gram_liver <- CLiver

    dAplas_free <- (QR * CVR * Free) + (QK * CVK * Free) + (QL * CVL * Free) +
    (QAdi*CVAdi*Free) + (QBra*CVBra*Free) + (QGon*CVGon*Free) + (QHea*CVHea*Free) +
    (QLun*CVLun*Free) +(QMus*CVMus*Free) +(QSki*CVSki*Free)+(QSpl*CVL*Free)+(QPan*CVL*Free)+
    (QGI*CVL*Free)- (QC * CA * Free) + dAefflux

    dingestion <- 0

    Atissue <- Aplas_free + AR + AAdi + ABra + AGon + AHea+ ALun +
    AMus + ASki + ASpl+ APan + AKb + Afil + ALumen+ AGI + APTC + AL
    Aloss <- Aurine + Afeces
    Atotal <- Atissue + Aloss

    list(c(
        "dAR" = dAR, "dAAdi" = dAAdi, "dABra" = dABra, "dAGon" = dAGon,
        "dAHea" = dAHea, "dALun" = dALun, "dAMus" = dAMus, "dASki" = dASki,
        "dASpl" = dASpl, "dAPan"=dAPan,
        "dAdif" = dAdif, "dA_baso" = dA_baso, "dAKb" = dAKb,
        "dACl" = dACl, "dAefflux" = dAefflux,
        "dA_apical" = dA_apical, "dAPTC" = dAPTC, "dAfil" = dAfil,
        "dAurine" = dAurine, "dALumen" = dALumen, "dAGI" = dAGI,
        "dAabsLumen" = dAabsLumen, "dAfeces" = dAfeces,
        "dAL" = dAL, "dAbile" = dAbile, "dAplas_free" = dAplas_free,
        "dingestion" = dingestion
      ),
      "amount_per_gram_liver" = amount_per_gram_liver,
      "Atissue" = Atissue, "Aloss" = Aloss, "Atotal" = Atotal,
      "CR" = CR, "CVR" = CVR,
      "CAdi"=CAdi, "CVAdi"=CVAdi,
      "CBra"=CBra, "CVBra"=CVBra,
      "CGon"=CGon, "CVGon"=CVGon,
      "CHea"=CHea, "CVHea"=CVHea, 
      "CLun"=CLun, "CVLun"=CVLun, 
      "CMus"=CMus, "CVMus"=CVMus, 
      "CSki"=CSki, "CVSki"=CVSki,
      "CSpl"=CSpl, "CVSpl"=CVSpl, 
      "Cpan"=Cpan, "CVPan"=CVPan, 
      "CKb" = CKb,  "CVK" = CVK, "CPTC" = CPTC,
      "Cfil" = Cfil,
      "CL" = CL, "CVL" = CVL, 
      "CGI" = CGI, "CVGI" = CVGI, 
      "CA_free" = CA_free, "CA" = CA)
})
}

#=========================
# 10. Population driver
#=========================
#' Run the extended PBK model across a popgen virtual population
#'
#' Generates a virtual population with .generate_population() and solves the
#' ODE system once per individual, using that individual's popgen-derived
#' organ mass/flow (Bone -> rest of body; see the file header for the full
#' mapping) via .create.params.population(). The administered dose and every
#' chemical-specific PK parameter are identical across individuals; only
#' physiology varies.
#'
#' @param user_input List combining:
#'   - the population-generation fields required by .generate_population()
#'     (n, dataset, age_range, bmi_range, height_range, prob_male,
#'     ethnicity_probs, population_type, optional seed), and
#'   - the same chemical/dosing fields Extended_Model.r's .create.params()
#'     expects (chemical, admin_type, admin_dose, admin_time, ingestion,
#'     ingestion_time, exp_type, duration, exposure_time, optional
#'     time_scale). BW is NOT supplied here -- popgen generates it per
#'     individual.
#' @param solver,rtol,atol passed through to deSolve::ode().
#' @return list(
#'   population = data.frame, one row per individual (popgen demographics,
#'     organ mass/flow, and the id used to join against `results`),
#'   results = data.frame stacking every individual's full ODE time-course,
#'     tagged by `id`
#' )
#' @export
#'
.run_population_extended <- function(user_input, solver = "lsodes", rtol = 1e-5, atol = 1e-5) {

  .check_required(user_input, c(.required_population_fields,
                                 "chemical", "admin_type", "exp_type", "duration", "exposure_time"))

  gen <- .generate_population(user_input)
  pop <- gen$pop
  message(sprintf("Generated %d individuals (%d discarded by popgen's rejection rules)",
                   nrow(pop), gen$n_discarded))

  chem <- .get_chemical_vars(user_input$chemical)

  results_list <- vector("list", nrow(pop))
  for (i in seq_len(nrow(pop))) {
    ind <- pop[i, ]
    params <- .create.params.population(user_input, ind, chem)
    inits <- .create.inits(params)
    events <- .create.events(params)

    sol <- as.data.frame(deSolve::ode(
      times = user_input$exposure_time, func = .ode.func, y = inits,
      parms = params, events = events, method = solver, rtol = rtol, atol = atol
    ))
    sol$id <- ind[["id"]]
    results_list[[i]] <- sol
  }

  results <- do.call(rbind, results_list)

  list(population = pop, results = results)
}

# --- Example usage ---------------------------------------------------------
user_input <- list(
  # popgen population-generation parameters (all required)
  n = 100, dataset = "ICRP", age_range = c(65, 70), bmi_range = c(20, 24),
  height_range = c(180, 190), prob_male = 1, ethnicity_probs = c(1, 0, 0),
  population_type = "Realistic", seed = 123,
  # chemical / dosing parameters (same as Extended_Model.r, minus BW)
  # admin_dose is non-zero and ingestion is 0, so this is a single oral bolus
  # dose -> admin_type must be "bolus" (routes admin_dose into ALumen via
  # .create.events()); admin_type "oral" would instead read the dose from
  # `ingestion`, which is 0 here, silently giving a zero dose.
  chemical = "PFOA", admin_type = "bolus", exp_type = "pharmacokinetics",
  ingestion = 0, ingestion_time = 0, admin_dose = 3.99, admin_time = 0,
  duration = 500, time_scale = "days",
  exposure_time = sort(unique(c(seq(0, 500, 1), 500)))
)
out <- .run_population_extended(user_input)
head(out$population)
head(out$results)

# --- Population percentile plot: 2.5th / 50th / 97.5th of plasma concentration (CA) ---
# CA (total plasma concentration, ug/L) is the headline PBK output; swap the
# "CA" column below for e.g. "CL" (liver) or "amount_per_gram_liver" to plot
# a different compartment the same way.
percentiles_CA <- out$results %>%
  group_by(time) %>%
  summarise(
    p2.5  = quantile(CA, probs = 0.025, na.rm = TRUE),
    p50   = quantile(CA, probs = 0.5,   na.rm = TRUE),
    p97.5 = quantile(CA, probs = 0.975, na.rm = TRUE),
    .groups = "drop"
  ) %>%
  pivot_longer(cols = c(p2.5, p50, p97.5), names_to = "percentile", values_to = "CA") %>%
  mutate(percentile = factor(percentile, levels = c("p2.5", "p50", "p97.5"),
                              labels = c("2.5th percentile", "Median (50th)", "97.5th percentile")))

theme_percentile <- theme_classic() +
  theme(
    text = element_text(size = 14, family = "sans"),
    axis.title = element_text(size = 15, face = "bold"),
    axis.text = element_text(size = 12, color = "black"),
    axis.line = element_line(color = "black", linewidth = 0.6),
    axis.ticks = element_line(color = "black", linewidth = 0.5),
    legend.title = element_blank(),
    legend.text = element_text(size = 12),
    legend.position = "top",
    plot.title = element_text(size = 16, face = "bold")
  )
plasma_exp <- read.csv("exp_data_plasma.csv") %>% select("time", "PFOA")

# Observed data is a separate layer with its own x/y/color mapping
# (inherit.aes = FALSE), since plasma_exp has no "percentile" column to
# satisfy the line layers' color/linetype/linewidth aesthetics.
obs_label <- "Observed (exp_data_plasma.csv)"

p_percentiles <- ggplot(percentiles_CA, aes(x = time, y = CA, color = percentile,
                                             linetype = percentile, linewidth = percentile)) +
  geom_line() +
  geom_point(data = plasma_exp, aes(x = time, y = PFOA, color = obs_label),
             inherit.aes = FALSE, shape = 21, fill = "white", size = 3, stroke = 1) +
  scale_color_manual(values = setNames(
    c("#6da7ec", "#2a78d6", "#6da7ec", "#0b0b0b"),
    c("2.5th percentile", "Median (50th)", "97.5th percentile", obs_label)
  )) +
  scale_linetype_manual(values = c("2.5th percentile" = "dashed",
                                    "Median (50th)" = "solid",
                                    "97.5th percentile" = "dashed")) +
  scale_linewidth_manual(values = c("2.5th percentile" = 0.7,
                                     "Median (50th)" = 1.1,
                                     "97.5th percentile" = 0.7)) +
  # color has a 4th level ("Observed") that linetype/linewidth don't, so
  # ggplot can't auto-merge the three legends -- merge them manually into a
  # single legend keyed on color, with per-entry line/point styling.
  guides(
    linetype = "none",
    linewidth = "none",
    color = guide_legend(
      title = NULL,
      override.aes = list(
        linetype = c("dashed", "solid", "dashed", "blank"),
        linewidth = c(0.7, 1.1, 0.7, NA),
        shape = c(NA, NA, NA, 21),
        fill = c(NA, NA, NA, "white")
      )
    )
  ) +
  labs(
    x = paste0("Time (", user_input$time_scale, ")"),
    y = "Plasma concentration, CA (µg/L)",
    title = paste0("Population PBK simulation — ", user_input$chemical,
                    " (n = ", nrow(out$population), ")")
  ) +
  theme_percentile

print(p_percentiles)

ggsave("population_percentiles_CA.png", p_percentiles, width = 8, height = 6, dpi = 300)
